    "purpose": "Bu dersin amacı, işletmelerin finansal kararlarını analiz edebilecek, yatırım ve finansman alternatiflerini değerlendirebilecek, risk-getiri ilişkisini kavrayarak sermaye bütçelemesi, sermaye maliyeti ve sermaye yapısı konularında rasyonel kararlar verebilecek bireyler yetiştirmektir.",
    "content": "Bu ders, finansal yönetimin temel kavramlarını ve karar alanlarını kapsamaktadır. Ders kapsamında getiri ve risk kavramları, risk-getiri ilişkisi, sermaye varlıklarını fiyatlama modeli, yatırım projelerinin nakit akışlarının belirlenmesi, proje değerleme yöntemleri ve riskin dikkate alınması konuları ele alınır. Ayrıca, sermaye maliyeti bileşenleri, finansman kaynakları, sermaye yapısı kararları ve kar payı dağıtım politikaları incelenir.",
    "methods": "Teorik anlatım, sınıf içi tartışma ve soru-cevap",
