    "term": "Güz",
    "instructor": "Prof. Dr. MUSTAFA FEDAİ ÇAVUŞ",
    "purpose": "Örgütlerde insan davranışlarının nedenlerini anlamak, analiz etmek ve gerekli çözümler üreterek uygun örgütsel ortam ve yönetim tarzı oluşturmaya çalışmak. Yönetici ve yönetilenlerin örgütsel amaçların gerçekleştirilmesindeki rollerini araştırmak.",
    "content": "Algılama, iletişim, önder ve önderlik, otorite, güç ve etkileme, grup ve grup dinamiği, güdüleme, çatışma, örgütsel değişim, örgüt kültürü ve stres konuları dersin içeriğini oluşturmaktadır",
