    "purpose": "Öğrencilerin teorik yöntemler aracılığı ile menkul kıymet seçimi, portföy yönetilmesi ve yatırım değerlendirmesi konularında bilgi sahibi olması hedeflenmekte; çeşitli problem çözümleri ile öğrencilerin yatırım yapma ve portföy oluşturma becerilerinin geliştirilmesi amaçlanmaktadır.",
    "content": "Portföy Yönetimi Kuramı, Sermaye Varlıklarını Fiyatlama Modeli, Hisse Senedi ve Tahvil Değerleme",
    "methods": "Ders, öğretim üyesinin kuramsal çerçeveyi sunduğu anlatım yöntemi ile öğrencilerin aktif katılımını esas alan sunum ve tartışma temelli yöntemlerin birlikte kullanıldığı karma bir öğretim yaklaşımıyla yürütülmektedir. Seçili konular öğrenciler tarafından makale temelli seminer sunumları şeklinde ele alınmakta, her sunum sonrası eleştirel tartışma yapılmaktadır. Ders kapsamında temel teorik modellerin matematiksel altyapısı çözümlemeli anlatım yoluyla aktarılmakta; ampirik çalışmalar üzerinden yöntem tartışmaları yürütülmektedir. Ayrıca öğrenci sunumları, yönlendirilmiş okuma, karşılaştırmalı literatür analizi ve eleştirel değerlendirme tekniklerinden yararlanılmaktadır.",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
