      "Menkul kıymetler ve portföy yönetimi kapsamındaki ileri kuramsal yaklaşımları eleştirel biçimde analiz eder.",
      "Finans ve sermaye piyasaları alanındaki modelleri karşılaştırarak özgün araştırma problemleri geliştirir.",
