      "Üretim İşletmelerinde Direkt İlk Madde ve Malzeme Bütçesi ile Direkt İşçilik Bütçesinin Hazırlanması",
      "Üretim İşletmelerinde Genel Üretim Giderleri Bütçesinin Hazırlanması",
      "Esnek Güg Bütçesi Üretim İşletmelerinde Faaliyet Giderleri Bütçesinin Hazırlanması",
      "Üretim İşletmelerinde Proforma SMM Tablosu",
      "Bilanço ve Gelir Tablosunun Hazırlanması",
      "Nakit Bütçesinin Hazırlanması Bütçe Sapmalarının Analizi",
      "Ticaret İşletmelerinde Genel Bütçenin Hazırlanması",
