    "purpose": "Bu dersin amacı, maliyet muhasebesinde kullanılan geleneksel yöntemlerin ötesine geçerek çağdaş maliyet yönetimi tekniklerini ve stratejik maliyet analizini öğretmektir. Öğrencilerden, modern işletme ortamında maliyet bilgilerinin stratejik karar alma süreçlerine katkısını değerlendirebilmeleri ve yeni yaklaşımlar geliştirebilmeleri beklenmektedir.",
    "content": "Ders; faaliyet tabanlı maliyetleme, hedef maliyetleme, yaşam döngüsü maliyetleme, kalite maliyetleri, kaizen maliyetleme, çevresel maliyet muhasebesi, stratejik maliyet yönetimi, değer zinciri analizi, maliyet etkenleri ve dijitalleşmenin maliyet sistemlerine etkilerini kapsar.",
