    "term": "Güz",
    "purpose": "Bu dersin amacı, PROCESS Makro modelleri yardımıyla aracılık analizlerinin teorik temellere dayanarak öğrencilere anlatılmasıdır. Bu dersin sonunda öğrenciler, basit veya direkt ilişki incelemesinin ötesine geçerek, “Nasıl?” sorusuna cevap bulabileceklerdir. Ayrıca öğrenciler daha kompleks aracılık, düzenleyicilik veya durumsal aracılık etki analizleri için bu derste altyapı oluşturacaklardır.",
    "content": "Alt konu başlıkları: Aracılık Analizleri İçin Teorik Bilgilerin Verilmesi, PROCESS Makro Uygulamasının Tanıtılması, Aracılık Analizlerine Giriş, Basit Aracılık Analizi, Pazarlamada Basit Aracılık Analiz Örneklerinin İrdelenmesi, Paralel Aracılık Analizi, Pazarlamada Paralel Aracılık Analiz Örneklerinin İrdelenmesi, Serisel Aracılık Analizi, Pazarlamada Serisel Aracılık Analiz Örneklerinin İrdelenmesi, Düzenleyicilik Analizine Giriş.",
