    "instructor": "Dr. Öğr. Üyesi MEHMET FATİH AÇAR",
    "purpose": "Bu dersin amacı, öğrencilere pazarlama iletişimi anlayışının bütüncül bir perspektiften nasıl yapılandığını kavratmak; reklam, halkla ilişkiler, satış tutundurma, kişisel satış ve dijital medya gibi iletişim araçlarının entegrasyonunu öğretmek; marka kimliği ve kurumsal imajın sürdürülebilir biçimde yönetilmesi için gerekli bilgi ve becerileri kazandırmaktır.",
    "content": "Bu ders, bütünleşik pazarlama iletişiminin kavramsal temellerini, gelişim sürecini ve uygulama alanlarını kapsamaktadır. Reklam, halkla ilişkiler, satış tutundurma, kişisel satış, doğrudan pazarlama ve dijital medya gibi pazarlama iletişimi araçlarının bütüncül bir yaklaşımla yönetilmesi üzerinde durulmaktadır. Ayrıca marka iletişimi, içerik stratejileri, yeni medya uygulamaları ve iletişim planlama süreçleri ele alınmakta; işletmelerin hedef kitleleriyle tutarlı, etkileşimli ve ölçülebilir iletişim kurma becerileri geliştirilmektedir.",
    "methods": "Ters-yüz sınıf, Anlatım, Beyin fırtınası",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "8",
      "9",
      "12"
    ],
    "outcomes": [
      "Bütünleşik pazarlama iletişimi kapsamındaki ileri kuramsal yaklaşımları eleştirel biçimde analiz eder.",
      "Pazarlama yönetimi alanındaki modelleri karşılaştırarak özgün araştırma problemleri geliştirir.",
      "Bütünleşik pazarlama iletişimi kapsamında uygun araştırma modelini tasarlar ve uygular.",
      "Bütünleşik pazarlama iletişimi bulgularını yönetsel, toplumsal ve etik etkileriyle değerlendirir.",
      "Bütünleşik pazarlama iletişimi alanındaki bilimsel kanıtlardan özgün strateji ve araştırma çıkarımları geliştirir."
    ],
