    "instructor": "Doç. Dr. İLKER KEFE",
    "purpose": "Bu dersin amacı, finansal bilgi manipülasyonlarının teorik temellerini, tespit yöntemlerini ve önleme mekanizmalarını doktora düzeyinde analiz etmektir. Finansal raporlamada etik dışı uygulamaların nedenlerini, yöneticilerin teşvik mekanizmalarını ve kurumsal yönetişimle olan ilişkisini ele alır.",
    "content": "Ders, kazanç yönetimi, yaratıcı muhasebe, finansal tablo hileleri, kurumsal yönetişim zafiyetleri, denetim mekanizmaları ve finansal manipülasyon tespit modelleri gibi konuları kapsamaktadır. Uygulamalı örnekler ve akademik araştırmalar aracılığıyla manipülasyonun işletme performansı, yatırımcı davranışı ve piyasa güvenilirliği üzerindeki etkileri tartışılır.",
    "methods": "Anlatım, Alıştırma & Problem Çözme, Soru & Cevap",
