    "practice": 0,
    "term": "Güz",
    "purpose": "Bu derste, lisans ve yüksek lisans seviyesindeki muhasebe derslerinde verilemeyen daha özellikli muhasebe uygulamaları anlatılmaktadır.",
    "content": "Dersin konularını; İnşaat muhasebe uygulamaları, Banka muhasebe uygulamaları, konaklama muhasebe uygulamaları ve Sigorta muhasebe uygulamaları ve kooperatiflerde muhasebe uygulamaları gibi konular oluşturmaktadır.",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
