      "Muhasebe ve denetim alanındaki modelleri karşılaştırarak özgün araştırma problemleri geliştirir.",
      "İhtisas muhasebeleri kapsamında uygun araştırma modelini tasarlar ve uygular.",
      "İhtisas muhasebeleri bulgularını yönetsel, toplumsal ve etik etkileriyle değerlendirir.",
      "İhtisas muhasebeleri alanındaki bilimsel kanıtlardan özgün strateji ve araştırma çıkarımları geliştirir."
