    "code": "ISL985",
    "name": "ÖRGÜTLERDE İNSAN DAVRANIŞI",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Prof. Dr. MUSTAFA FEDAİ ÇAVUŞ",
    "purpose": "Dersin amacı örgüt içerisindeki çalışan bireylerin davranışlarının grup, örgüt ve çevre değişkenlerini dikkate alarak incelenmesi ve analiz edilmesidir.",
    "content": "Örgütsel Davranışın Bilimsel Temelleri; Örgütsel Davranışın Tarihsel Gelişimi; Araştırma Teknikleri; Örgüt İçinde Birey ve Kişilik; Tutumlar ve İş Tatmini; Bireysel Farklılıkların Temelleri Biyografik Karakteristikler Yetenekler ve Öğrenme; Örgüt Kültürü, Örgütlerde Grup ve Süreçleri; Örgütlerde Grupla Çalışma Teknikleri ve Katılımlı Yönetim; Örgütlerde Güdüleme Süreci ve Kuramları; Örgütlerde Liderlik ve Kuramları; Örgütlerde Çatışma; Örgütlerde Stres ve Yönetimi; Örgütsel Çevre ve Teknoloji; Örgütsel Değişme, Geliştirme, Takım Çalışmaları; Örgütlerde Güç ve Politika; Örgütlerde Etik Davranışlar, Yönetimi ve Kontrolü.",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
    "sdgs": [
      "5",
      "8",
      "16"
    ],
    "outcomes": [
      "Örgütlerde insan davranışı kapsamındaki ileri kuramsal yaklaşımları eleştirel biçimde analiz eder.",
      "Yönetim ve örgüt alanındaki modelleri karşılaştırarak özgün araştırma problemleri geliştirir.",
      "Örgütlerde insan davranışı kapsamında uygun araştırma modelini tasarlar ve uygular.",
      "Örgütlerde insan davranışı bulgularını yönetsel, toplumsal ve etik etkileriyle değerlendirir.",
      "Örgütlerde insan davranışı alanındaki bilimsel kanıtlardan özgün strateji ve araştırma çıkarımları geliştirir."
    ],
