    "purpose": "u dersin amacı, pozitif psikoloji ve pozitif yönetim yaklaşımlarını doktora düzeyinde ele alarak öğrencilerin pozitif liderlik, iyi oluş, pozitif psikolojik sermaye ve örgütsel pozitiflik konularını kuramsal ve ampirik açıdan analiz edebilmesini sağlamaktır. Ayrıca öğrencilerin farklı sektörlerdeki pozitif yönetim uygulamalarını eleştirel biçimde değerlendirmesi ve özgün modeller geliştirmesi hedeflenir.",
    "content": "Ders; pozitif psikoloji temelleri, iyi oluş ve mutluluk kuramları, pozitif örgütsel davranış, pozitif liderlik, psikolojik sermaye, dayanıklılık, çalışan mutluluğu ve pozitif performans yönetimi gibi konuları kapsamaktadır. Ampirik araştırmaların incelenmesi, sektörel uygulamaların değerlendirilmesi ve model geliştirme çalışmaları ders içeriğinin temel bileşenleridir.",
