    "content": "Temel Kavramlar, Günümüz işletmeciliğinde yenilik yönetiminin yeri ve önemi, yenilik yaratma çevresi, yenilik türleri, yenilik yaratma süreci, yaratıcı düşünme teknikleri, araştırma ve geliştirme,",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
