    "content": "Kurumsal yönetimin ve finansal raporlama sürecinin önemli bir parçası olan muhasebe denetimi kavramsal olarak ele alınacak. Bağımsız denetçilerin görev ve sorumlulukları, denetim sürecinin aşamaları, denetim raporunun hazırlanması konuları üzerinde durulacaktır.",
