    "content": "Ki-kare uygunluk, homojenlik, Bağımsızlık testleri, binom test, akış Testi, tek örnek Kolmogorov-Smirnov testi, Wilcoxon testi, Sign testi, Mann-Whitney U, Kolmogorov-Smirnov Z, Kruskal Wallis, Friedman, Cochran’s Q testleri",
