    "purpose": "İşletmelerde çok önemli bir yeri olan “insan” unsurunu anlamak ve işletmenin iç ve dış çevresel faktörlerin, yöneticilerin ve işletmede tüm çalışanların davranışları üzerindeki etkisini analiz etmek",
    "content": "Örgütsel davranış ile ilgili temel kavramlar, statü ve rol davranışı, kişilik, tutumlar ve tutum davranış ilişkisi, motivasyon, liderlik, gruplar, grup süreçleri ve dinamikleri, kurumsal ve kişilerarası iletişim, örgüt kültürü, kültürün yönetim fonksiyonlarına etkisi, örgütsel değişim ve örgüt geliştirme, çatışma ve çözüm yolları, iş tatmini ve stres",
    "methods": "Kuramsal anlatım, problem çözme, bilimsel kaynak incelemesi ve işletme bulgularının tartışılması.",
    "resources": "Dersin gerçek OBS kaynakları; güncel işletme literatürü, hakemli makaleler ve ilgili ulusal/uluslararası veri kaynakları.",
