      "Finans ve sermaye piyasaları alanındaki modelleri karşılaştırarak özgün araştırma problemleri geliştirir.",
      "Stratejik finansal yönetim uygulamaları kapsamında uygun araştırma modelini tasarlar ve uygular.",
