    "purpose": "Bu ders; pazarlama araştırması süreci, araştırma yöntemleri, örnekleme yöntemleri ve uygulama modelleri, veri toplama yöntemleri, verilerin analizi, araştırma raporunun hazırlanması ve sonuçların karar almada kullanımı hakkında bilgilendirmeyi amaçlar.",
